package com.makemytrip.makemytrip.controllers;
import com.makemytrip.makemytrip.models.*;import com.makemytrip.makemytrip.repositories.*;import com.makemytrip.makemytrip.services.FeatureService;import com.makemytrip.makemytrip.services.FlightTrackingService;import com.makemytrip.makemytrip.services.LegacyBookingMirrorService;import com.makemytrip.makemytrip.services.CancellationService;import com.makemytrip.makemytrip.services.FlightStatusService;import com.makemytrip.makemytrip.services.SeatService;import com.makemytrip.makemytrip.services.RoomService;import com.makemytrip.makemytrip.services.PricingEngine;import com.makemytrip.makemytrip.services.PriceFreezeService;import com.makemytrip.makemytrip.services.RecommendationService;import com.makemytrip.makemytrip.services.ReviewService;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.*;import java.time.*;
@RestController @RequestMapping("/api") public class TravelFeatureController {
 private final FeatureService service;private final FlightTrackingService tracking;private final LegacyBookingMirrorService legacyMirror;private final CancellationService cancellation;private final FlightStatusService flightStatus;private final SeatService seatService;private final RoomService roomService;private final PricingEngine pricing;private final PriceFreezeService priceFreeze;private final RecommendationService recommendationService;private final ReviewService reviewService;private final BookingRepository bookings;private final RefundRepository refunds;private final ReviewRepository reviews;private final ReviewFlagRepository flags;private final ReviewReplyRepository replies;private final UserRepository users;private final com.makemytrip.makemytrip.repositories.FlightRepository flights;private final com.makemytrip.makemytrip.repositories.HotelRepository hotels;
 public TravelFeatureController(FeatureService s,FlightTrackingService tracking,LegacyBookingMirrorService legacyMirror,CancellationService cancellation,FlightStatusService flightStatus,SeatService seatService,RoomService roomService,PricingEngine pricing,PriceFreezeService priceFreeze,RecommendationService recommendationService,ReviewService reviewService,BookingRepository b,RefundRepository f,ReviewRepository r,ReviewFlagRepository flags,ReviewReplyRepository replies,UserRepository u,com.makemytrip.makemytrip.repositories.FlightRepository flights,com.makemytrip.makemytrip.repositories.HotelRepository hotels){service=s;this.tracking=tracking;this.legacyMirror=legacyMirror;this.cancellation=cancellation;this.flightStatus=flightStatus;this.seatService=seatService;this.roomService=roomService;this.pricing=pricing;this.priceFreeze=priceFreeze;this.recommendationService=recommendationService;this.reviewService=reviewService;bookings=b;refunds=f;reviews=r;this.flags=flags;this.replies=replies;users=u;this.flights=flights;this.hotels=hotels;}
 String uid(Authentication a){if(a==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);Users u=users.findByEmail(a.getName());if(u==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return u.getId();}
 @PostMapping("/bookings/{id}/cancel") public Refund cancel(@PathVariable String id,@RequestBody Map<String,String> body,Authentication a){CancellationReason reason;try{reason=CancellationReason.valueOf(body.getOrDefault("reason","OTHER"));}catch(RuntimeException ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid cancellation reason");}return cancellation.cancel(id,uid(a),reason);}
 @GetMapping("/bookings/{id}/refund") public Refund refund(@PathVariable String id,Authentication a){Refund r=refunds.findByBookingIdAndUserId(id,uid(a));if(r==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);return r;}
 @GetMapping("/users/me/refunds") public List<Refund> myRefunds(Authentication a){return refunds.findByUserId(uid(a));}
 @GetMapping("/bookings/{id}") public Booking getBooking(@PathVariable String id,Authentication a){return service.owned(id,uid(a));}
 @GetMapping("/users/me/bookings") public List<Booking> myBookings(Authentication a){return bookings.findByUserId(uid(a));}
 @PutMapping("/admin/bookings/{id}/complete") public Booking completeBooking(@PathVariable String id){Booking b=bookings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));if(b.getStatus()!=Booking.Status.CONFIRMED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only confirmed bookings can be completed");b.setStatus(Booking.Status.COMPLETED);Booking saved=bookings.save(b);legacyMirror.sync(saved);return saved;}
 @GetMapping("/admin/refunds") public List<Refund> adminRefunds(){return refunds.findAll();}
 @PutMapping("/admin/refunds/{id}/status") public Refund refundStatus(@PathVariable String id,@RequestBody Map<String,String> d){Refund r=refunds.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Refund not found"));try{r.setRefundStatus(Refund.Status.valueOf(d.get("status")));}catch(RuntimeException ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid refund status");}if(r.getRefundStatus()==Refund.Status.PROCESSED||r.getRefundStatus()==Refund.Status.COMPLETED)r.setProcessedDate(Instant.now());return refunds.save(r);}
 @PostMapping("/reviews") public Review createReview(@RequestBody Review r,Authentication a){return reviewService.create(r,uid(a));}
 @GetMapping("/reviews") public List<Review> reviewList(@RequestParam(required=false) String targetType,@RequestParam(required=false) String targetId,@RequestParam(required=false) Integer rating,@RequestParam(required=false) Boolean photos,@RequestParam(defaultValue="newest") String sort){if((targetType==null)!=(targetId==null))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"targetType and targetId must be supplied together");List<Review> l;if(targetId==null)l=reviews.findByStatus(Review.Status.APPROVED);else{Review.TargetType parsed;try{parsed=Review.TargetType.valueOf(targetType.toUpperCase(Locale.ROOT));}catch(IllegalArgumentException ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid target type");}l=reviews.findByTargetTypeAndTargetIdAndStatus(parsed,targetId,Review.Status.APPROVED);}if(rating!=null){if(rating<1||rating>5)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Rating must be 1-5");l.removeIf(x->x.getRating()!=rating);}if(photos!=null)l.removeIf(x->photos!=(x.getPhotos()!=null&&!x.getPhotos().isEmpty()));Comparator<Review> c=switch(sort){case "newest"->Comparator.comparing(Review::getCreatedAt).reversed();case "highest-rated"->Comparator.comparingInt(Review::getRating).reversed();case "lowest-rated"->Comparator.comparingInt(Review::getRating);case "most-helpful"->Comparator.comparingInt(Review::getHelpfulCount).reversed();default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid review sort");};l.sort(c);return l;}
 @GetMapping("/reviews/{id}") public Review getReview(@PathVariable String id){Review r=reviewService.get(id);if(r.getStatus()!=Review.Status.APPROVED)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Review not found");return r;}
 @PutMapping("/reviews/{id}") public Review editReview(@PathVariable String id,@RequestBody Review d,Authentication a){return reviewService.edit(id,d,uid(a));}
 @DeleteMapping("/reviews/{id}") public void deleteReview(@PathVariable String id,Authentication a){reviewService.delete(id,uid(a));}
 @PutMapping("/admin/reviews/{id}/moderate") public Review moderate(@PathVariable String id,@RequestBody Map<String,String> d){try{return reviewService.moderate(id,Review.Status.valueOf(d.get("status")));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid review status");}}
 @PostMapping("/reviews/{id}/reply") public ReviewReply reply(@PathVariable String id,@RequestBody ReviewReply d,Authentication a){getReview(id);if(d.getText()==null||d.getText().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Reply text is required");ReviewReply reply=new ReviewReply();reply.setReviewId(id);reply.setUserId(uid(a));reply.setText(d.getText().trim());return replies.save(reply);}
 @GetMapping("/reviews/{id}/replies") public List<ReviewReply> replies(@PathVariable String id){getReview(id);return replies.findByReviewId(id);}
 @PutMapping("/reviews/{id}/replies/{replyId}") public ReviewReply editReply(@PathVariable String id,@PathVariable String replyId,@RequestBody ReviewReply d,Authentication a){if(d.getText()==null||d.getText().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Reply text is required");ReviewReply reply=replies.findById(replyId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Reply not found"));if(!id.equals(reply.getReviewId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Reply not found");if(!uid(a).equals(reply.getUserId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);reply.setTextAndTouch(d.getText().trim());return replies.save(reply);}
 @DeleteMapping("/reviews/{id}/replies/{replyId}") public void deleteReply(@PathVariable String id,@PathVariable String replyId,Authentication a){ReviewReply reply=replies.findById(replyId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Reply not found"));if(!id.equals(reply.getReviewId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Reply not found");if(!uid(a).equals(reply.getUserId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);replies.delete(reply);}
 @PostMapping("/reviews/{id}/helpful") public Review helpful(@PathVariable String id,Authentication a){return reviewService.helpful(id,uid(a));}
 @PostMapping("/reviews/{id}/flag") public ReviewFlag flag(@PathVariable String id,@RequestBody Map<String,String>d,Authentication a){getReview(id);if(flags.existsByReviewIdAndUserId(id,uid(a)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Review already flagged by this user");ReviewFlag f=new ReviewFlag();f.setReviewId(id);f.setUserId(uid(a));try{f.setReason(ReviewFlag.Reason.valueOf(d.get("reason")));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid flag reason");}return flags.save(f);}
 @GetMapping("/admin/reviews/flagged") public List<ReviewFlag> flagged(){return flags.findAll();}
 @GetMapping("/flights/{id}/status") public FlightStatus status(@PathVariable String id){return flightStatus.get(id);}
 @GetMapping("/flights/status") public FlightStatus statusByNumber(@RequestParam String flightNumber){return flightStatus.byNumber(flightNumber);}
 @PostMapping("/admin/flights/{id}/status") public FlightStatus statusSet(@PathVariable String id,@RequestBody FlightStatus d){return flightStatus.update(id,d);}
 @PostMapping("/flights/{id}/track") public TrackedFlight track(@PathVariable String id,Authentication a){return tracking.track(uid(a),id);}
 @DeleteMapping("/flights/{id}/track") public void untrack(@PathVariable String id,Authentication a){tracking.untrack(uid(a),id);}
 @GetMapping("/users/me/tracked-flights") public List<TrackedFlight> tracked(Authentication a){return tracking.list(uid(a));}
 @GetMapping("/flights/{id}/seats") public List<Seat> seats(@PathVariable String id){if(!flights.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Flight not found");return seatService.list(id);}
 @PostMapping("/admin/flights/{id}/seats") public Seat addSeat(@PathVariable String id,@RequestBody Seat seat){if(!flights.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Flight not found");if(seat.getSeatNumber()==null||seat.getSeatNumber().isBlank()||!Double.isFinite(seat.getPrice())||seat.getPrice()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Seat number and nonnegative price are required");if(seat.getStatus()==null)seat.setStatus(Seat.Status.AVAILABLE);return seatService.save(id,seat);}
 @PostMapping("/bookings/{id}/seat") public Booking seat(@PathVariable String id,@RequestBody Map<String,String>d,Authentication a){Booking b=service.owned(id,uid(a));if(b.getBookingType()!=Booking.Type.FLIGHT||b.getStatus()!=Booking.Status.CONFIRMED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Seat selection requires a confirmed flight booking");String number=d.get("seatNumber");if(number==null||number.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"seatNumber is required");if(number.equals(b.getSeatNumber()))return b;Seat reserved=seatService.claim(b.getFlightId(),number,id);if(reserved==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Seat unavailable or not found");if(b.getSeatNumber()!=null)seatService.release(b.getFlightId(),b.getSeatNumber(),id);b.setTotalPrice(Math.round((b.getTotalPrice()-b.getSelectionSurcharge()+reserved.getPrice()*b.getQuantity())*100d)/100d);b.setSelectionSurcharge(reserved.getPrice()*b.getQuantity());b.setSeatNumber(number);Booking saved=bookings.save(b);legacyMirror.sync(saved);return saved;}
 @DeleteMapping("/bookings/{id}/seat") public Booking unseat(@PathVariable String id,Authentication a){Booking b=service.owned(id,uid(a));if(b.getSeatNumber()!=null){seatService.release(b.getFlightId(),b.getSeatNumber(),id);b.setSeatNumber(null);b.setTotalPrice(Math.max(0,b.getTotalPrice()-b.getSelectionSurcharge()));b.setSelectionSurcharge(0);}Booking saved=bookings.save(b);legacyMirror.sync(saved);return saved;}
 @GetMapping("/hotels/{id}/rooms") public List<Room> rooms(@PathVariable String id){if(!hotels.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Hotel not found");return roomService.list(id);}
 @PostMapping("/hotels/{id}/rooms") public Room addRoom(@PathVariable String id,@RequestBody Room room){if(!hotels.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Hotel not found");if(room.getRoomType()==null||room.getRoomType().isBlank()||!Double.isFinite(room.getPrice())||room.getPrice()<0||!Double.isFinite(room.getUpgradePrice())||room.getUpgradePrice()<0||room.getAvailableQuantity()<0||room.getCapacity()<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Room type, capacity, nonnegative price and availability are required");return roomService.save(id,room);}
 @PostMapping("/bookings/{id}/room") public Booking room(@PathVariable String id,@RequestBody Map<String,String>d,Authentication a){Booking b=service.owned(id,uid(a));if(b.getBookingType()!=Booking.Type.HOTEL||b.getStatus()!=Booking.Status.CONFIRMED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Room selection requires a confirmed hotel booking");String type=d.get("roomType");if(type==null||type.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"roomType is required");if(type.equals(b.getRoomType()))return b;Room reserved=roomService.claim(b.getHotelId(),type,b.getQuantity());if(reserved==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Room unavailable or not found");if(b.getRoomId()!=null)roomService.release(b.getRoomId(),b.getQuantity());double hotelBase=hotels.findById(b.getHotelId()).map(Hotel::getPricePerNight).orElse(0d);double surcharge=Math.max(0,reserved.getPrice()-hotelBase)*b.getQuantity()+(reserved.isPremium()?reserved.getUpgradePrice()*b.getQuantity():0d);b.setTotalPrice(Math.round((b.getTotalPrice()-b.getSelectionSurcharge()+surcharge)*100d)/100d);b.setSelectionSurcharge(surcharge);b.setRoomType(type);b.setRoomId(reserved.getId());Booking saved=bookings.save(b);legacyMirror.sync(saved);return saved;}
 @GetMapping("/flights/{id}/price-history") public List<PriceHistory> flightPriceHistory(@PathVariable String id){return pricing.history("FLIGHT",id);}
 @GetMapping("/hotels/{id}/price-history") public List<PriceHistory> hotelPriceHistory(@PathVariable String id){return pricing.history("HOTEL",id);}
 @GetMapping("/flights/{id}/current-price") public PriceHistory currentFlightPrice(@PathVariable String id){return pricing.currentFlight(id);}
 @GetMapping("/hotels/{id}/current-price") public PriceHistory currentHotelPrice(@PathVariable String id){return pricing.currentHotel(id);}
 @GetMapping("/admin/pricing/rules") public PricingRules pricingRules(){return pricing.getRules();}
 @PutMapping("/admin/pricing/rules") public PricingRules updatePricingRules(@RequestBody PricingRules rules){return pricing.updateRules(rules);}
 @PostMapping("/bookings/{id}/price-freeze") public PriceFreeze freeze(@PathVariable String id,Authentication a){return priceFreeze.create(id,uid(a));}
 @GetMapping("/price-freezes/{id}") public PriceFreeze freezeGet(@PathVariable String id,Authentication a){return priceFreeze.get(id,uid(a));}
 @PostMapping("/price-freezes/{id}/use") public PriceFreeze useFreeze(@PathVariable String id,Authentication a){return priceFreeze.use(id,uid(a));}
 @GetMapping("/recommendations") public List<Recommendation> recommendations(Authentication a){return recommendationService.forUser(uid(a));}
 @PostMapping("/recommendations/{id}/feedback") public Recommendation feedback(@PathVariable String id,@RequestBody Map<String,String>d,Authentication a){Recommendation.Feedback feedback;try{feedback=Recommendation.Feedback.valueOf(d.get("feedback"));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid feedback value");}return recommendationService.feedback(id,uid(a),feedback);}
}
